/**
 * Test: Heightmap Data Validation
 *
 * The heightmap is generated by CyFractal and normalized to [0, 1].
 * Validates dimensions, value ranges, and that variation exists.
 */

import {
  generateTestMap, assert, reportResults,
  ALL_MAP_TYPES
} from './_test-utils.js';

for (const mapType of ALL_MAP_TYPES) {
  console.log(`\n--- ${mapType} ---`);

  const map = generateTestMap(mapType);
  const W = map.width;
  const H = map.height;

  // heightmap must exist and be a 2D array
  assert(Array.isArray(map.heightmap),
    `${mapType}: heightmap is an array`);
  assert(map.heightmap.length === H,
    `${mapType}: heightmap has ${H} rows (got ${map.heightmap.length})`);

  let allValid = true;
  let hasNaN = false;
  let hasInfinity = false;
  let outOfRange = 0;
  let minVal = Infinity;
  let maxVal = -Infinity;
  let total = 0;
  let count = 0;

  for (let y = 0; y < H; y++) {
    const row = map.heightmap[y];
    if (!Array.isArray(row) || row.length !== W) {
      allValid = false;
      continue;
    }

    for (let x = 0; x < W; x++) {
      const val = row[x];
      count++;
      if (typeof val !== 'number') { allValid = false; continue; }
      if (Number.isNaN(val)) { hasNaN = true; continue; }
      if (!Number.isFinite(val)) { hasInfinity = true; continue; }
      if (val < 0 || val > 1) outOfRange++;
      if (val < minVal) minVal = val;
      if (val > maxVal) maxVal = val;
      total += val;
    }
  }

  assert(allValid,
    `${mapType}: all heightmap rows have correct width and numeric values`);
  assert(!hasNaN,
    `${mapType}: no NaN values in heightmap`);
  assert(!hasInfinity,
    `${mapType}: no Infinity values in heightmap`);
  assert(outOfRange === 0,
    `${mapType}: all heightmap values in [0, 1] (out of range: ${outOfRange})`);

  // Should have variation (not all identical)
  const range = maxVal - minVal;
  assert(range > 0.01,
    `${mapType}: heightmap has variation (range: ${range.toFixed(4)}, min: ${minVal.toFixed(4)}, max: ${maxVal.toFixed(4)})`);

  console.log(`  info: range [${minVal.toFixed(3)}, ${maxVal.toFixed(3)}], mean ${(total / count).toFixed(3)}`);
}

reportResults('test-heightmap');
